--
-- Table structure for table `__PREFIX__shop_goods_sku`
--

DROP TABLE IF EXISTS `__PREFIX__shop_goods_sku`;

--
-- Create the table if it not exists
--

CREATE TABLE `__PREFIX__shop_goods_sku` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `goods_id` int(11) NOT NULL COMMENT '商品 ID',
  `sku_key` varchar(100) NOT NULL DEFAULT '' COMMENT '规格值组合键(排序后的 spec_value_id 用 _ 连接;无规格留空)',
  `sn` varchar(100) NOT NULL DEFAULT '' COMMENT 'SKU 货号',
  `price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '售价',
  `market_price` decimal(10,2) DEFAULT NULL COMMENT '市场价',
  `cost_price` decimal(10,2) DEFAULT NULL COMMENT '成本价',
  `stock` int(11) NOT NULL DEFAULT '0' COMMENT '库存',
  `frozen_stock` int(11) NOT NULL DEFAULT '0' COMMENT '冻结库存(预占;第一版未用)',
  `weight` decimal(10,2) DEFAULT NULL COMMENT '重量',
  `image` varchar(255) DEFAULT '' COMMENT 'SKU 图片',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_goods_skukey` (`goods_id`,`sku_key`),
  KEY `idx_goods_id` (`goods_id`),
  KEY `idx_sku_sn` (`sn`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商品 SKU';

