  KEY `idx_goods_id` (`goods_id`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单项快照';

