--
-- Table structure for table `__PREFIX__shop_address`
--

DROP TABLE IF EXISTS `__PREFIX__shop_address`;

--
-- Create the table if it not exists
--

CREATE TABLE `__PREFIX__shop_address` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `name` varchar(100) NOT NULL DEFAULT '',
  `phone` varchar(20) NOT NULL DEFAULT '',
  `country_id` int(11) NOT NULL DEFAULT 0 COMMENT '国家地区ID',
  `country` varchar(100) NOT NULL DEFAULT '' COMMENT '国家地区名称',
  `province_id` int(11) DEFAULT '0',
  `province` varchar(100) DEFAULT '',
  `city` varchar(100) DEFAULT '',
  `address` varchar(500) NOT NULL DEFAULT '',
  `zip_code` varchar(20) DEFAULT '',
  `is_default` tinyint(1) NOT NULL DEFAULT '0',
  `status` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB ROW_FORMAT=DYNAMIC AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='收货地址';

