  `oppose` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '反对数',
  `create_user` varchar(30) NOT NULL COMMENT '创建人员',
  `update_user` varchar(20) NOT NULL COMMENT '更新人员',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  `gtype` char(1) NOT NULL DEFAULT '4',
  `gid` varchar(20) NOT NULL DEFAULT '',
  `gnote` varchar(100) NOT NULL DEFAULT '',
  `aucode` int(10) DEFAULT NULL COMMENT '语言统一code',
  `custom_tpl` varchar(255) DEFAULT '' COMMENT '详情页模版',
  PRIMARY KEY (`id`),
  UNIQUE KEY `content_acode_aucode` (`acode`,`aucode`),
  KEY `ay_content_scode` (`scode`),
  KEY `ay_content_subscode` (`subscode`),
  KEY `ay_content_acode` (`acode`),
  KEY `ay_content_filename` (`filename`),
  KEY `ay_content_date` (`date`),
  KEY `ay_content_sorting` (`sorting`),
  KEY `ay_content_status` (`status`),
  KEY `content_aucode` (`aucode`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=263 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CMS文章内容';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `__PREFIX__cms_content`
--

/*!40000 ALTER TABLE `__PREFIX__cms_content` DISABLE KEYS */;
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (1,'cn','1','','BadouCMS 商城简介','#333333','','','admin','本站','','2018-04-11 17:26:11','','','','<h2>关于 BadouCMS</h2>\n<p>BadouCMS（八斗网站管理系统）是一套面向企业网站、品牌官网和内容型项目的开源网站管理系统。系统基于 ThinkPHP 8 与 Layui 构建，坚持清晰、实用和便于二次开发的设计思路，希望让网站建设不再停留在一次性交付，而是成为企业可以长期维护、持续扩展的数字化基础。无论是公司介绍、新闻资讯、产品展示，还是会员服务与在线商城，都可以在同一套后台中完成管理。</p>\n<p>我们重视内容管理的灵活性。BadouCMS 支持多语言区域、多模型、自定义字段、单页与列表内容、栏目管理、标签调用、条件筛选和多种路由方式。运营人员可以按照实际业务建立新闻、案例、产品、问答、下载等不同内容模型，不必让所有数据都挤在固定结构中。栏目图片、SEO 标题、关键词、描述、轮播图、友情链接、留言表单和网站地图等常用能力也被统一纳入后台，让日常更新更加直接。</p>\n<p>在权限和用户体系方面，系统提供后台角色权限、内容浏览权限、会员等级、注册登录、资料维护、收藏与评论等基础能力。通过模块化结构和事件机制，开发者可以在不破坏核心代码的前提下增加业务模块、模板标签或第三方服务。系统同时提供 API、缓存、数据导入导出、系统升级和内容安全处理等基础设施，方便项目从展示型网站逐步发展为具有真实业务流程的平台。</p>\n\n<h2>内容与商城的一体化</h2>\n<p>本项目在 BadouCMS 内容能力之上整合了完整的商城模块。商品并不是孤立的数据，而是与栏目、品牌、内容和会员体系协同工作。后台可以维护商品分类、品牌、规格、规格值、SKU、价格、市场价、库存、销量、重量、图集和详情内容，也可以通过规格模板快速建立常用商品组合。对于不同商品形态，运营人员能够分别控制上下架状态、库存和展示信息，减少重复录入。</p>\n<p>前台商城覆盖商品列表、商品详情、品牌展示、搜索筛选、购物车、收货地址、订单确认和会员订单中心。用户可以选择商品规格和数量，完成购物车管理与结算；订单创建后，后台可以处理付款状态、发货、快递单号、卖家备注、取消与完成等流程。系统同时保留支付记录、发货记录和订单日志，便于管理人员追踪订单状态，减少业务处理中信息分散的问题。</p>\n<p>为了支持持续运营，商城还提供优惠券、领取记录、使用条件、商品收藏、购买后评价和积分配置。售后模块覆盖售后申请、审核、拒绝、退货收货和退款记录，并可根据项目需要对接支付渠道完成原路退款。物流部分采用可扩展接口，基础页面能够展示发货记录，安装物流查询服务后还可以接入实时轨迹。每一项能力都围绕真实交易流程组织，而不是简单拼接几个展示页面。</p>\n\n<h2>面向多语言与长期运营</h2>\n<p>BadouCMS 本身支持多语言内容管理，商城模块也延续了这一思路。商品可以按照语言维护独立版本，不同语言下可分别设置标题、详情、SEO 信息、价格、库存、参数和上下架状态；需要统一时，也可以选择指定内容同步到其他语言。这样的结构既适合中文商城，也方便企业逐步建设英文或其他语言站点，避免后期因为数据结构受限而重新开发整套系统。</p>\n<p>内容与交易共用一套模板体系，是本项目的重要特点。CMS 标签负责栏目、文章、轮播图和单页内容，商城标签负责商品、品牌、价格和推荐数据。模板开发者可以根据品牌视觉自由组织页面，同时让后台数据保持可编辑。当前商城前台采用响应式布局，兼顾桌面端和移动端，并通过统一的组件与样式规范保持导航、列表、详情、问答、新闻和会员页面的一致体验。</p>\n<p>在实际部署与维护中，系统尽量把配置、内容与模板分开管理。站点信息、商城参数、支付和配送方式可以在后台集中设置，图片与附件通过统一上传流程维护，核心业务则按照模块划分。开发者能够针对项目选择本地存储或扩展对象存储，接入邮件、短信、物流和其他服务；运营人员无需理解代码，也可以独立完成栏目调整、内容发布、商品更新和订单处理。这种分工让网站上线后的日常维护更稳定，也便于后续升级和功能扩展。</p>\n\n<h2>我们的方向</h2>\n<p>我们相信，一套好用的网站系统应当让内容人员容易上手，让开发者容易理解，也让企业拥有继续发展的空间。BadouCMS 不追求堆叠没有实际用途的功能，而是围绕内容发布、商品经营、会员服务和订单履约完善每一个常用环节。清晰的数据结构、可替换的模板、可扩展的模块和可独立维护的多语言内容，共同构成这套系统的基础。</p>\n<p>未来我们会继续改进后台操作体验、商城交易流程、移动端页面、模板标签和插件接口，并根据真实项目反馈完善细节。无论用于企业官网、制造业产品展示、品牌零售商城，还是外贸多语言站点，BadouCMS 都希望提供一套可靠、可控、能够长期迭代的技术方案，让企业把更多精力放在内容、产品与客户服务本身。</p>','','','BadouCMS,开源CMS,商城系统,ThinkPHP8,多语言商城,内容管理系统','BadouCMS 是基于 ThinkPHP 8 与 Layui 构建的开源网站管理系统。本项目在内容管理、多语言、多模型和会员体系基础上，进一步整合商品、SKU、购物车、订单、支付、物流、优惠券与售后能力，为企业官网和品牌商城提供一套统一、灵活、可持续扩展的解决方案。',255,'1','0','0','0',1507,0,0,'admin','Admin','2018-04-11 17:26:11','2026-07-24 08:26:57','4','','',NULL,''),(195,'cn','9020','','铜合金滚花铆钉','','耐磨滚花紧固件','brass-knurled-rivet','shop','temp028','','2026-07-18 23:33:25','/uploads/20260718/1f864b5568524e43c56116b98745c93c.jpg','','','<p>铜合金滚花铆钉适用于装配固定和装饰五金，支持不同直径、长度及表面处理。</p>','铜铆钉,滚花铆钉,紧固件','','铜合金滚花铆钉','耐磨滚花紧固件',11,'1','0','1','0',4,0,0,'shop','shop','2026-07-18 23:33:25','2026-07-19 21:38:37','4','','',1101,''),(170,'cn','9013','','Apple','','','','Adminhtgl','','','2026-07-14 20:02:04','','','','','','','','',255,'1','0','0','0',0,0,0,'shop','shop','2026-07-14 20:02:04','2026-07-14 20:02:04','4','','',5,''),(246,'en','9031','','How Do You Ensure Consistent Quality in Batch Production?','','','faq-quality-consistency-68','Administrator','This Site','','2026-07-15 09:00:00','','','','<p>Before production, we review the drawings and process plan. After first-article approval, in-process and final inspections follow documented standards, with records kept for critical dimensions. Material certificates and inspection reports are available when required.</p>','faq','','quality control,inspection reports','First-article approval, in-process inspections and final records keep batch quality consistent.',50,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1405,''),(247,'en','9031','','How Do I Submit a Drawing and Get a Quote?','','','faq-drawing-quotation-84','Administrator','This Site','','2026-07-17 09:00:00','','','','<p>Please provide PDF, STEP, IGES or CAD drawings and specify the material, quantity, tolerances, surface treatment and special inspection requirements. Our engineers will review the process and provide pricing and lead-time feedback.</p>','faq','','drawings,quotation','Send drawings, materials, quantities and tolerances for a process review, quotation and lead-time estimate.',30,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1403,''),(248,'en','9031','','What Is the Lead Time for a Standard Order?','','','faq-order-lead-time-86','Administrator','This Site','','2026-07-18 09:00:00','','','','<p>Lead time depends on the material, process complexity, quantity and surface treatment requirements. Standard samples are usually completed within 7 to 15 business days after the drawing and process are confirmed. A detailed schedule is provided for batch orders with the quotation.</p>','faq','','lead time,order schedule','Samples usually take 7 to 15 business days; batch orders follow the confirmed production schedule.',20,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1402,''),(249,'en','9031','','What Precision Component Machining Services Do You Offer?','','','faq-machining-services-50','Administrator','This Site','','2026-07-19 09:00:00','','','','<p>We provide custom CNC turning, CNC lathe parts, automatic lathe parts, milling and other precision metal component machining services. Each project can be evaluated from drawings, samples or dimensional requirements.</p>','faq','','precision machining,service scope','Custom CNC turning, automatic lathe, milling and other precision metal part services.',10,'1','0','0','0',2,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1401,''),(261,'en','9014','','Apple','','','apple','Adminhtgl','','','2026-07-14 20:02:04','','','','','','','','',255,'1','0','0','0',0,0,0,'shop','shop','2026-07-24 10:05:21','2026-07-24 10:05:21','4','','',5,''),(252,'cn','9037','','配送信息','#333333','','','Adminhtgl','本站','','2026-07-22 22:32:32','','','','','','','','',255,'1','0','0','0',2,0,0,'Adminhtgl','Adminhtgl','2026-07-22 22:32:32','2026-07-23 09:37:33','4','0','',NULL,''),(262,'en','9032','','Key Points for Dimensional Control in CNC Lathe Parts Machining','','','cnc-turning-dimension-control-en','Administrator','This Site','','2026-07-18 10:00:00','','','','<p>Dimensional consistency in CNC lathe parts is closely related to tool condition, workholding, cutting parameters and inspection frequency.</p><p>Confirming datums and tolerance requirements before production, then documenting first-article and in-process inspections, can effectively reduce dimensional variation in batch machining.</p>','Industry News,CNC Turning','','CNC turning,dimensional control','Learn about the key controls that affect dimensional consistency in CNC lathe parts machining.',20,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-24 10:05:21','2026-07-24 10:05:21','4','','',1302,''),(254,'cn','9039','','隐私协议','#333333','','','Adminhtgl','本站','','2026-07-22 22:33:13','','','','','','','','',255,'1','0','0','0',3,0,0,'Adminhtgl','Adminhtgl','2026-07-22 22:33:13','2026-07-23 09:37:29','4','0','',NULL,''),(256,'en','9036','','About Us','#333333','','','Adminhtgl','Website','','2026-07-23 17:41:32','','','','<h2>About BadouCMS</h2><p>BadouCMS is an open-source content management system for corporate websites, brand sites and content-driven projects. Built on ThinkPHP 8 and Layui, it focuses on clarity, practical administration and easy customization. Company profiles, news, product catalogs, member services and online stores can all be managed from one administration platform.</p><p>BadouCMS provides multilingual areas, multiple content models, custom fields, single pages, lists, sections, tags, conditional filters and flexible routing. Teams can build news, case studies, products, FAQs and downloads around their own business structure. Section images, SEO titles, keywords, descriptions, slides, links, forms and sitemaps are managed in the same backend.</p><p>The permission and member systems include administrator roles, content access control, member levels, registration, login, profile management, favorites and comments. Its modular architecture and event system allow developers to add business modules, template tags and third-party services without changing the core. APIs, caching, data import and export, upgrades and content security tools support projects as they grow.</p><h2>Integrated Content and Commerce</h2><p>This project combines the BadouCMS content features with a complete commerce module. Products work together with sections, brands, content and members instead of existing as isolated records. The backend supports product categories, brands, specifications, specification values, SKUs, prices, market prices, stock, sales, weight, image galleries and product details.</p><p>The storefront covers product lists, product details, brand pages, search, filters, shopping carts, addresses, checkout and member order centers. Customers can choose product specifications and quantities, then complete checkout. After an order is created, administrators can manage payment status, shipping, tracking numbers, seller notes, cancellations and completion. Payment, shipment and order logs make every status easy to track.</p><p>For ongoing operations, the store includes coupons, usage conditions, favorites, product reviews and points. After-sales workflows cover applications, review, rejection, returns and refunds, with payment integrations available for original-method refunds. Shipping is organized around extensible interfaces, so tracking services can be added when required.</p><h2>Built for Multilingual, Long-Term Operations</h2><p>BadouCMS supports multilingual content management, and the commerce module follows the same approach. Products can have independent language versions with separate titles, details, SEO information, prices, stock, specifications and publication status. This structure supports both Chinese stores and future English or multilingual sites without forcing a complete redevelopment.</p><p>CMS and commerce share one template system. CMS tags provide sections, articles, slides and single pages, while commerce tags provide products, brands, prices and recommendations. Responsive layouts serve desktop and mobile users, with consistent navigation and page components across product, news, FAQ and member experiences.</p><p>Site settings, store parameters, payment and shipping methods can be managed centrally. Images and attachments use one upload workflow, while core business features remain organized by module. Developers can connect storage, email, SMS, logistics and other services as needed; content teams can manage sections, publish content, update products and process orders without writing code.</p><h2>Our Direction</h2><p>A good website system should be easy for content teams to use, easy for developers to understand and flexible enough for a business to keep growing. BadouCMS focuses on content publishing, product operations, member services and order fulfillment, supported by clear data structures, replaceable templates, extensible modules and independently maintained multilingual content.</p><p>We will continue improving administration, commerce workflows, mobile pages, template tags and extension interfaces based on real project feedback. Whether it is used for a corporate site, a manufacturing catalog, a brand store or a multilingual export website, BadouCMS aims to provide a reliable and controllable foundation for long-term iteration.</p>','','','about us,company,precision machining,manufacturing','Learn about our company, manufacturing capabilities and commitment to reliable precision machining.',255,'1','0','0','0',12,0,0,'Adminhtgl','adminhtgl','2026-07-23 17:41:32','2026-07-24 10:33:44','4','0','',NULL,NULL),(257,'en','9038','','Shipping Information','#333333','','','Adminhtgl','Website','','2026-07-23 17:41:32','','','','<h2>Shipping Information</h2><p>We process orders after payment and order details have been confirmed. Delivery time depends on product availability, order quantity, destination and the selected shipping method.</p><p>After dispatch, tracking information will be added to the order when available. Please make sure that your shipping address and contact details are complete and accurate before submitting an order.</p><p>For questions about delivery status, shipping arrangements or special requirements, please contact our team through the site contact details.</p>','','','shipping information,delivery','Find information about order processing, delivery and shipping arrangements.',255,'1','0','0','0',1,0,0,'Adminhtgl','adminhtgl','2026-07-23 17:41:32','2026-07-24 10:33:53','4','0','',NULL,NULL),(258,'en','9040','','Privacy Policy','#333333','','','Adminhtgl','Website','','2026-07-23 17:41:32','','','','<h2>Privacy Policy</h2><p>We respect your privacy and handle personal information only when it is needed to provide website, account, shopping and support services.</p><p>Information such as contact details, order information and delivery details may be used to process requests, provide services, communicate with you and improve the site. We do not sell personal information to third parties.</p><p>We apply reasonable technical and administrative measures to protect stored information. If you have questions about your information or need assistance with a privacy request, please contact us through the site contact details.</p>','','','privacy policy,data protection','Read how we handle personal information and protect customer data.',255,'1','0','0','0',1,0,0,'Adminhtgl','adminhtgl','2026-07-23 17:41:32','2026-07-24 10:33:50','4','0','',NULL,NULL),(235,'cn','2','','精密零件加工如何提升交付稳定性','','','precision-parts-delivery-stability','管理员','本站','','2026-07-19 10:00:00','/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg','','','<p>精密零件项目要稳定交付，关键在于把图纸评审、工艺规划、首件确认和过程检验串联起来。</p><p>通过标准化工艺卡、关键尺寸记录和节点复核，可以提前识别加工风险，让每一批产品都保持一致的质量和交期。</p>','行业资讯,精密加工','','精密零件,交付管理','从图纸评审到过程检验，梳理精密零件稳定交付的关键环节。',10,'1','0','0','0',30,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-23 17:46:37','4','','',1301,''),(236,'cn','2','','CNC车床件加工中的尺寸控制要点','','','cnc-turning-dimension-control','管理员','本站','','2026-07-18 10:00:00','','','','<p>CNC车床件的尺寸稳定性与刀具状态、装夹方式、切削参数和检测频次密切相关。</p><p>生产前确认基准和公差要求，生产中做好首件及巡检记录，能有效减少批量加工中的尺寸波动。</p>','行业资讯,CNC车床','','CNC车床,尺寸控制','了解 CNC 车床件加工中影响尺寸稳定性的几个关键控制点。',20,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 19:20:00','4','','',1302,''),(237,'cn','2','','从材料选择到表面处理：提升零件使用寿命','','','material-surface-treatment-guide','管理员','本站','','2026-07-17 10:00:00','','','','<p>零件的使用寿命不仅取决于加工精度，也与材料性能、热处理方案和表面处理方式有关。</p><p>根据工作温度、载荷、耐磨和防腐要求选择合适的材料与工艺，才能兼顾性能、成本和批量交付效率。</p>','行业资讯,材料选择','','材料选择,表面处理','材料、热处理与表面处理的合理组合，能够帮助零件获得更长的使用寿命。',30,'1','0','0','0',2,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:48:06','4','','',1303,''),(238,'cn','9030','','你们支持哪些精密零件加工服务？','','','faq-machining-services','管理员','本站','','2026-07-19 09:00:00','','','','<p>我们提供 CNC 车削、数控车床件、自动车床件、铣削及多种精密金属零件的定制加工服务，可根据图纸、样品或尺寸要求进行评估。</p>','faq','','精密加工,服务范围','支持 CNC 车削、自动车床件及多种精密金属零件的定制加工。',10,'1','0','0','0',2,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:49:03','4','','',1401,''),(239,'cn','9030','','常规订单的交期需要多久？','','','faq-order-lead-time','管理员','本站','','2026-07-18 09:00:00','','','','<p>交期会根据材料、工艺复杂度、数量和表面处理要求确定。常规样品通常在确认图纸和工艺后 7 至 15 个工作日内完成，批量订单会在报价时给出明确排期。</p>','faq','','交期,订单周期','样品通常 7 至 15 个工作日完成，批量订单以确认后的排期为准。',20,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:49:02','4','','',1402,''),(240,'cn','9030','','如何确认图纸并获得报价？','','','faq-drawing-quotation','管理员','本站','','2026-07-17 09:00:00','','','','<p>请提供 PDF、STEP、IGES 或 CAD 图纸，并注明材料、数量、公差、表面处理和特殊检验要求。工程师会据此核对工艺并反馈报价与交期。</p>','faq','','图纸,报价','提供图纸、材料、数量和公差等信息后，我们会进行工艺评估并反馈报价。',30,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:49:01','4','','',1403,''),(241,'cn','9030','','支持哪些常用材料？','','','faq-materials','管理员','本站','','2026-07-16 09:00:00','','','','<p>常见材料包括铝合金、不锈钢、碳钢、黄铜、铜及工程塑料等。若有特殊材料或材料证明要求，请在询价时一并说明。</p>','faq','','加工材料,材料证明','可加工铝合金、不锈钢、碳钢、黄铜、铜及工程塑料等常用材料。',40,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:48:59','4','','',1404,''),(242,'cn','9030','','如何保证批量产品的质量一致性？','','','faq-quality-consistency','管理员','本站','','2026-07-15 09:00:00','','','','<p>我们会在生产前进行图纸和工艺评审，首件确认后按照检验规范执行巡检与终检，并保留关键尺寸记录。需要时还可提供材质证明和检验报告。</p>','faq','','质量控制,检验报告','通过首件确认、过程巡检和终检记录，保证批量产品的质量一致性。',50,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-20 22:49:00','4','','',1405,''),(245,'en','9031','','Which Common Materials Do You Support?','','','faq-materials-3','Administrator','This Site','','2026-07-16 09:00:00','','','','<p>Common materials include aluminum alloys, stainless steel, carbon steel, brass, copper and engineering plastics. Please mention any special material or material certification requirements when requesting a quote.</p>','faq','','machining materials,material certification','We machine common materials including aluminum, stainless steel, carbon steel, brass, copper and engineering plastics.',40,'1','0','0','0',0,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1404,''),(180,'en','9023','','Turned Parts and Shafts','','Custom precision turned shafts and parts','temp028-turning','shop','temp028','','2026-07-18 22:45:29',