074389be.jpg','','<h2>全能运动智能手表</h2><p>演示商品：心率、血氧和多运动模式监测，用于验证颜色与尺寸组合 SKU 效果。</p>','','','智能手表,运动手表,演示商品','全能运动智能手表演示数据',40,'1','0','0','0',12,0,0,'shop','shop','2026-07-16 16:38:46','2026-07-17 15:47:02','4','','',4,''),(162,'en','9015','','Smart Noise-Cancelling Bluetooth Headphones','','Dual-feedback ANC with up to 36 hours of battery life','demo-noise-cancelling-headphone-en','shop','','','2026-07-10 23:24:18','/uploads/20260720/39b9a6b3e1d18ac23c82dd4bc12b2432.jpg','/uploads/20260720/39b9a6b3e1d18ac23c82dd4bc12b2432.jpg','','<h2>Smart Noise-Cancelling Bluetooth Headphones</h2><p>Demo product with active noise cancellation, low-latency mode and fast charging. Use it to test SKU selection and price updates on the storefront.</p>','','','bluetooth headphones,noise cancelling headphones,demo product','Smart noise-cancelling Bluetooth headphones demo product.',10,'1','0','0','0',44,0,0,'shop','shop','2026-07-10 23:24:18','2026-07-23 17:44:46','4','','',1,''),(163,'en','9015','','Tri-Mode Wireless Mechanical Keyboard','','Switch between 2.4G, Bluetooth and wired connections','demo-wireless-mechanical-keyboard-en','shop','','','2026-07-10 23:24:18','/uploads/20260720/ade137b223746f9c47a3a1802ecb958d.jpg','/uploads/20260720/ade137b223746f9c47a3a1802ecb958d.jpg','','<h2>Tri-Mode Wireless Mechanical Keyboard</h2><p>Demo product with hot-swappable switches, RGB backlighting and multi-device switching. Use it to test a single specification with multiple SKUs.</p>','','','mechanical keyboard,wireless keyboard,demo product','Tri-mode wireless mechanical keyboard demo product.',20,'1','0','0','0',4,0,0,'shop','shop','2026-07-10 23:24:18','2026-07-11 10:31:29','4','','',2,''),(244,'en','9032','','How Precision Machining Improves Delivery Stability','','','precision-parts-delivery-stability-56','Administrator','This Site','','2026-07-19 10:00:00','/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg','','','<p>Stable delivery for precision parts depends on connecting drawing review, process planning, first-article approval and in-process inspection.</p><p>Standardized process sheets, critical-dimension records and milestone checks help identify machining risks early, keeping quality and lead times consistent across every batch.</p>','Industry News,Precision Machining','','precision machining,delivery stability','Key practices for stable delivery, from drawing review to in-process inspection.',10,'1','0','0','0',2,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1301,''),(164,'en','9015','','Portable Outdoor Bluetooth Speaker','','IPX7 waterproof design with dual-driver stereo sound','demo-portable-bluetooth-speaker-en','shop','','','2026-07-10 23:24:18','/uploads/20260720/9ebd94b3b0b549046804ad48d20214d1.jpg','/uploads/20260720/9ebd94b3b0b549046804ad48d20214d1.jpg','','<h2>Portable Outdoor Bluetooth Speaker</h2><p>Demo product with a waterproof enclosure, long battery life and stereo pairing. Use it to test stock and price changes across size SKUs.</p>','','','bluetooth speaker,outdoor speaker,demo product','Portable outdoor Bluetooth speaker demo product.',30,'1','0','0','0',2,0,0,'shop','shop','2026-07-10 23:24:18','2026-07-24 08:56:11','4','','',3,''),(165,'en','9015','','All-Round Sports Smartwatch','','Health monitoring and GPS workout tracking','demo-sport-smart-watch-en','shop','','','2026-07-10 23:24:18','/uploads/20260720/7745a9af73ad80d20d407fde074389be.jpg','/uploads/20260720/7745a9af73ad80d20d407fde074389be.jpg','','<h2>All-Round Sports Smartwatch</h2><p>Demo product with heart-rate, blood-oxygen and multi-sport tracking. Use it to test color and size SKU combinations.</p>','','','smartwatch,sports watch,demo product','All-round sports smartwatch demo product.',40,'1','0','0','0',0,0,0,'shop','shop','2026-07-10 23:24:18','2026-07-10 23:24:18','4','','',4,''),(243,'en','9032','','From Material Selection to Surface Treatment: Extending Part Service Life','','','material-surface-treatment-guide-66','Administrator','This Site','','2026-07-17 10:00:00','','','','<p>Part service life depends not only on machining accuracy, but also on material performance, heat treatment and surface treatment.</p><p>Selecting the right material and process for operating temperature, load, wear and corrosion requirements helps balance performance, cost and production efficiency.</p>','Industry News,Material Selection','','material selection,surface treatment','The right combination of material, heat treatment and surface treatment can extend part service life.',30,'1','0','0','0',2,0,0,'adminhtgl','adminhtgl','2026-07-20 19:20:00','2026-07-24 10:05:21','4','','',1303,''),(175,'cn','9020','','铆钉加工','','精密铆钉与紧固件定制加工','temp028-rivet','shop','temp028','','2026-07-18 22:45:29','/uploads/20260718/1f864b5568524e43c56116b98745c93c.jpg','','','<p>适用于机械设备、汽车配件及五金装配的精密铆钉加工服务。支持按图按样定制，提供稳定的尺寸控制与表面处理选择。</p>','铆钉加工,紧固件,精密加工','','铆钉加工,紧固件加工','精密铆钉与紧固件定制加工',10,'1','0','1','0',28,0,0,'shop','shop','2026-07-18 22:45:29','2026-07-23 20:21:37','4','','',1001,''),(176,'en','9021','','Rivet Machining','','Custom precision rivets and fasteners','temp028-rivet','shop','temp028','','2026-07-18 22:45:29','/uploads/20260718/1f864b5568524e43c56116b98745c93c.jpg','','','<p>Precision rivet machining for machinery, automotive parts and hardware assembly. Made to drawing or sample with stable dimensional control and surface finish options.</p>','rivet machining,fasteners,precision machining','','rivet machining,fasteners','Custom precision rivets and fasteners',10,'1','0','1','0',32,0,0,'shop','shop','2026-07-18 22:45:29','2026-07-24 09:40:22','4','','',1001,''),(179,'cn','9022','','车削件轴件','','精密车削轴类零件定制','temp028-turning','shop','temp028','','2026-07-18 22:45:29','/uploads/20260718/f71599a107ba84e5c93dd9215a6227db.jpg','','','<p>面向传动、连接和支撑部位的车削件与轴件加工。可按图纸制作不同直径、长度与公差要求的机械零件。</p>','车削件,轴件,机械零件','','车削件,轴件加工','精密车削轴类零件定制',20,'1','0','1','0',4,0,0,'shop','shop','2026-07-18 22:45:29','2026-07-22 21:58:58','4','','',1002,'');
