INSERT INTO `__PREFIX__cms_site` (`id`, `acode`, `title`, `subtitle`, `domain`, `logo`, `keywords`, `description`, `icp`, `theme`, `statistical`, `copyright`) VALUES (1,'cn','badoucms网站管理系统','永久开源免费的PHP企业网站开发建设管理系统','','/uploads/20250622/83f3aee5bdea54e652ef497fc45f4ab7.png','cms,免费cms,开源cms,企业cms,建站cms','BadouCMS是一套全新内核且永久开源免费的PHP企业网站开发建设管理系统，是一套高效、简洁、 强悍的可免费商用的PHP CMS源码，能够满足各类企业网站开发建设的需要。系统采用简单到想哭的模板标签，只要懂HTML就可快速开发企业网站。官方提供了大量网站模板免费下载和使用，将致力于为广大开发者和企业提供最佳的网站开发建设解决方案。','苏ICP备88888888号','shop','','BadouCMS All Rights Reserved.'),(2,'en','BadouCMS Shop','Open-source e-commerce and content management for modern businesses','','/uploads/20250622/83f3aee5bdea54e652ef497fc45f4ab7.png','BadouCMS, open-source CMS, e-commerce platform, ThinkPHP 8, multilingual shop, content management','BadouCMS is an open-source website and e-commerce platform built with ThinkPHP 8 and Layui. It combines multilingual content management, product catalogs, shopping carts, orders, payments, shipping, coupons and after-sales workflows for business websites and brand stores.','','shop','','BadouCMS. All rights reserved.');
/*!40000 ALTER TABLE `__PREFIX__cms_site` ENABLE KEYS */;

